'use strict';
// A small lifetime ledger survives the rolling diary. It records acts, never invents achievements.
const LifeLegacy=(()=>{
 const text=(s,n=380)=>String(s||'').replace(/\s+/g,' ').trim().slice(0,n),kinds=['birth','work','family','journey','decision','project','relationship','loss'];
 function classify(e){const key=e.key||'';if(key.startsWith('society-role-'))return {kind:'decision',weight:80};if(key.startsWith('decision-hazard-'))return {kind:'decision',weight:84};if(key.startsWith('decision-faith-'))return {kind:'project',weight:key.endsWith('-2')?93:80};if(key==='birth')return {kind:'birth',weight:100};if(key==='life-end')return {kind:'loss',weight:95};if(key==='human-family-support')return {kind:'family',weight:76};if(key.startsWith('human-path-')||key==='decision-human-road')return {kind:'decision',weight:70};if(key.startsWith('decision-project-')&&/-2$/.test(key))return {kind:'project',weight:90};if(e.kind==='project-ending')return {kind:'project',weight:90};if(key.startsWith('bond-dream-')&&/-2$/.test(key))return {kind:'relationship',weight:86};if(key.startsWith('bond-promise-'))return {kind:'relationship',weight:80};if(key.startsWith('travel-'))return {kind:'journey',weight:68};if(key.startsWith('career-')||e.title==='งานแรกในเส้นทางชีวิต')return {kind:'work',weight:75};if(key==='decision-love'||key==='decision-family'||/child|partner/.test(key)&&e.kind==='family')return {kind:'family',weight:88};if(key.startsWith('decision-human-path-'))return {kind:'decision',weight:85};if(e.kind==='loss')return {kind:'loss',weight:64};if(e.kind==='decision')return {kind:'decision',weight:48};return null}
 function ensure(s){if(s.lifeLegacy)return s.lifeLegacy;const l=s.lifeLegacy={version:1,entries:[],kingdoms:[s.homeKingdom??s.kingdom],careers:[],decisions:s.turn||0,firstAge:s.age||0,migrated:!!(s.age||s.turn),finalized:false};for(const e of [...(s.diary?.entries||[])].reverse())observe(s,e);if(s.job!==null&&!l.careers.includes(s.job))l.careers.push(s.job);for(const k of s.route||[])if(!l.kingdoms.includes(k))l.kingdoms.push(k);return l}
 function observe(s,e){const l=s.lifeLegacy||ensure(s);if(l.finalized)return;l.decisions=s.turn||0;if(!l.kingdoms.includes(s.kingdom)&&l.kingdoms.length<KINGDOMS.length)l.kingdoms.push(s.kingdom);if(s.job!==null&&!l.careers.includes(s.job)&&l.careers.length<40)l.careers.push(s.job);const c=classify(e);if(!c)return;const key=text(e.key||'entry-'+e.id,160);if(l.entries.some(x=>x.key===key))return;l.entries.push({key,title:text(e.title,290),summary:text(c.kind==='work'&&s.job!==null?'เริ่มทำงานเป็น'+JOBS[s.job][0]+' ใน'+KINGDOMS[s.kingdom][0]:e.paragraphs?.[0]||''),choice:text(e.choice,180),age:e.age??s.age,month:e.month||1,realm:Number.isInteger(e.realm)?e.realm:s.kingdom,kind:c.kind,weight:c.weight});if(l.entries.length>64){let drop=-1;for(let i=0;i<l.entries.length;i++)if(l.entries[i].kind!=='birth'&&l.entries[i].key!=='life-end'&&(drop<0||l.entries[i].weight<l.entries[drop].weight))drop=i;if(drop>=0)l.entries.splice(drop,1);else l.entries.shift()}}
 function seal(s){const l=ensure(s);if(l.finalized||!s.dead)return;l.decisions=s.turn;l.finalized=true;l.age=s.age;l.cause=text(s.cause,500)}
 function summary(s){const l=s.lifeLegacy,source=l?.entries||[],picked=source.filter(e=>!e.legacyEcologyMismatch&&e.kind!=='birth'&&e.kind!=='loss').map((e,index)=>({e,index})).sort((a,b)=>b.e.weight-a.e.weight||a.index-b.index).slice(0,5).map(x=>x.e).sort((a,b)=>a.age-b.age||a.month-b.month),careers=l?.careers?.length?l.careers:s.job!==null?[s.job]:[],worlds=l?.kingdoms?.length?l.kingdoms:[...new Set([s.homeKingdom??s.kingdom,...(s.route||[])])],people=typeof LifeBonds==='undefined'?[]:LifeBonds.memorial(s),departed=(s.bonds?.memorials||[]).slice(0,3),h=s.humanOrigin,clan=h&&!h.migrated&&typeof HumanOrigins!=='undefined'?HumanOrigins.clan(h.clanId):null;
  if(!people.length)for(const m of (s.household?.members||[]).filter(m=>m.alive).slice(0,3))people.push({name:m.name,role:m.role,race:m.race,text:m.role.split(' · ')[0]+' · คนในบ้านของคุณที่ '+KINGDOMS[s.homeKingdom??s.kingdom][0]});
  const title=s.job!==null?JOBS[s.job][0]:careers.length?JOBS[careers.at(-1)][0]:Engine.biological(s)<4?'ชีวิตเล็ก ๆ ในอ้อมแขนของบ้าน':Engine.biological(s)<18?'ช่วงเวลาที่เติบโตกับคนใกล้ตัว':'ชีวิตที่เลือกเดินด้วยตนเอง',origin=KINGDOMS[s.homeKingdom??s.kingdom][0],description='เกิดที่'+origin+(clan?' ในสกุล'+clan.name:'')+' คุณใช้ชีวิต '+s.age+' ปี'+(careers.length?' ผ่านงาน '+careers.length+' อาชีพ':'')+(worlds.length>1?' และเคยเรียก '+worlds.length+' อาณาจักรว่าบ้าน':'')+(s.turn?' เรื่องที่คุณเลือกยังอยู่ในบันทึกเหล่านี้':' ช่วงเวลาของคุณยังอยู่ในบันทึกของบ้านหลังนี้');return {title,description,origin,clan,people:people.slice(0,3),departed,careers,worlds,milestones:picked,migrated:!!l?.migrated,decisions:s.turn,projects:(s.projects?.completed||[]).length,ending:s.ending||'บันทึกหนึ่งชีวิต'};
 }
 function valid(s){const l=s.lifeLegacy;if(l===undefined)return true;const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b,int=(n,a,b)=>Number.isInteger(n)&&num(n,a,b),str=(x,n)=>typeof x==='string'&&x.length<=n;return l&&l.version===1&&Array.isArray(l.entries)&&l.entries.length<=64&&new Set(l.entries.map(e=>e?.key)).size===l.entries.length&&l.entries.every(e=>e&&str(e.key,160)&&str(e.title,290)&&str(e.summary,380)&&str(e.choice,180)&&num(e.age,0,s.age)&&int(e.month,1,12)&&int(e.realm,0,KINGDOMS.length-1)&&kinds.includes(e.kind)&&int(e.weight,0,100))&&Array.isArray(l.kingdoms)&&l.kingdoms.length<=KINGDOMS.length&&new Set(l.kingdoms).size===l.kingdoms.length&&l.kingdoms.every(k=>int(k,0,KINGDOMS.length-1))&&Array.isArray(l.careers)&&l.careers.length<=40&&new Set(l.careers).size===l.careers.length&&l.careers.every(j=>int(j,0,JOBS.length-1))&&int(l.decisions,0,20000)&&num(l.firstAge,0,s.age)&&typeof l.migrated==='boolean'&&typeof l.finalized==='boolean'&&(!l.finalized||s.dead&&num(l.age,0,s.age)&&str(l.cause,500))}
 return {ensure,observe,seal,summary,valid};
})();
